/* Basic: declarations, operator precedence and constant expressions.
 * Watch the optimizer fold the constant arithmetic and drop the unused value. */
#include <stdio.h>

#define WIDTH 12
#define HEIGHT 5

int main(void) {
    int a = 7, b = 3;
    int result = a + b * 2;            /* * binds tighter than + */
    int grouped = (a + b) * 2;
    int area = WIDTH * HEIGHT;         /* both operands are constants */
    int border = 2 * (WIDTH + HEIGHT) - 4;
    int unused = area * 100;           /* never read: dead code */
    int remainder = -17 % 5;           /* C: the sign follows the dividend */
    int quotient = -17 / 5;            /* C: division truncates toward zero */
    double ratio = (double)area / border;
    unsigned int mask = 0xF0u | 0x0Fu;
    long big = 1L << 40;

    printf("result=%d grouped=%d\n", result, grouped);
    printf("area=%d border=%d ratio=%.4f\n", area, border, ratio);
    printf("-17 / 5 = %d, -17 %% 5 = %d\n", quotient, remainder);
    printf("mask=%u big=%ld\n", mask, big);
    return 0;
}

/* Intermediate: functions, nested loops, if/else chains, switch with
 * fall-through, do-while, break/continue and global state. */
#include <stdio.h>

#define LIMIT 30

enum Grade { FAIL, PASS, MERIT, DISTINCTION };

int checks = 0;

int is_prime(int n) {
    checks++;
    if (n < 2) return 0;
    if (n % 2 == 0) return n == 2;
    for (int d = 3; d * d <= n; d += 2) {
        if (n % d == 0) return 0;
    }
    return 1;
}

int collatz_length(long n) {
    int steps = 0;
    while (n != 1) {
        n = (n % 2 == 0) ? n / 2 : 3 * n + 1;
        steps++;
    }
    return steps;
}

enum Grade classify(int score) {
    if (score >= 85) return DISTINCTION;
    else if (score >= 70) return MERIT;
    else if (score >= 50) return PASS;
    return FAIL;
}

const char *grade_name(enum Grade g) {
    switch (g) {
    case DISTINCTION: return "distinction";
    case MERIT:       return "merit";
    case PASS:        return "pass";
    default:          return "fail";
    }
}

int digit_sum(int n) {
    int s = 0;
    do {
        s += n % 10;
        n /= 10;
    } while (n > 0);
    return s;
}

int main(void) {
    int primes = 0, longest = 0, longest_at = 0;
    for (int i = 1; i <= LIMIT; i++) {
        if (is_prime(i)) {
            printf("%d ", i);
            primes++;
        }
        int len = collatz_length(i);
        if (len > longest) { longest = len; longest_at = i; }
    }
    printf("\n%d primes below %d (%d checks)\n", primes, LIMIT, checks);
    printf("longest Collatz chain: %d steps from %d\n", longest, longest_at);

    int scores[6] = {92, 47, 70, 68, 85, 50};
    int counts[4] = {0};
    for (int i = 0; i < 6; i++) {
        enum Grade g = classify(scores[i]);
        counts[g]++;
        printf("score %3d -> %s\n", scores[i], grade_name(g));
    }

    /* switch fall-through: count vowels and how many are 'e' */
    const char *text = "the quick brown fox jumps over the lazy dog";
    int vowels = 0, es = 0, spaces = 0;
    for (int i = 0; text[i] != 0; i++) {
        switch (text[i]) {
        case 'e': es++;
        case 'a': case 'i': case 'o': case 'u':
            vowels++;
            break;
        case ' ':
            spaces++;
            continue;
        default:
            break;
        }
    }
    printf("vowels=%d e=%d words=%d digit_sum(98765)=%d\n", vowels, es, spaces + 1, digit_sum(98765));
    printf("grades: fail=%d pass=%d merit=%d distinction=%d\n", counts[FAIL], counts[PASS], counts[MERIT], counts[DISTINCTION]);
    return 0;
}

/* Intermediate: arrays, recursion, sorting, searching and 2-D matrices. */
#include <stdio.h>

#define N 12
#define M 4

int fib(int n) {
    if (n < 2) return n;
    return fib(n - 1) + fib(n - 2);
}

int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

long power(long base, int exp) {
    long result = 1;
    while (exp > 0) {
        if (exp & 1) result *= base;
        base *= base;
        exp >>= 1;
    }
    return result;
}

void swap(int a[], int i, int j) {
    int t = a[i];
    a[i] = a[j];
    a[j] = t;
}

int partition(int a[], int lo, int hi) {
    int pivot = a[hi];
    int i = lo - 1;
    for (int j = lo; j < hi; j++) {
        if (a[j] <= pivot) {
            i++;
            swap(a, i, j);
        }
    }
    swap(a, i + 1, hi);
    return i + 1;
}

void quicksort(int a[], int lo, int hi) {
    if (lo < hi) {
        int p = partition(a, lo, hi);
        quicksort(a, lo, p - 1);
        quicksort(a, p + 1, hi);
    }
}

int binary_search(int a[], int n, int key) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == key) return mid;
        if (a[mid] < key) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

void print_array(const char *label, int a[], int n) {
    printf("%s:", label);
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
}

int main(void) {
    int data[N] = {42, 7, 19, 3, 88, 51, 23, 7, 64, 12, 5, 30};
    print_array("input ", data, N);
    quicksort(data, 0, N - 1);
    print_array("sorted", data, N);
    printf("search 51 -> index %d, search 50 -> index %d\n", binary_search(data, N, 51), binary_search(data, N, 50));

    printf("fib:");
    for (int i = 0; i <= 15; i++) printf(" %d", fib(i));
    printf("\ngcd(462, 1071) = %d, 3^20 = %ld\n", gcd(462, 1071), power(3, 20));

    int a[M][M], b[M][M], c[M][M];
    for (int i = 0; i < M; i++)
        for (int j = 0; j < M; j++) {
            a[i][j] = i + j;
            b[i][j] = (i == j) ? 2 : i - j;
        }
    int trace = 0;
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < M; j++) {
            int sum = 0;
            for (int k = 0; k < M; k++) sum += a[i][k] * b[k][j];
            c[i][j] = sum;
        }
        trace += c[i][i];
    }
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < M; j++) printf("%5d", c[i][j]);
        printf("\n");
    }
    printf("trace = %d\n", trace);
    return 0;
}

/* Advanced: a multi-function toolkit -- a deterministic random generator,
 * statistics, dynamic programming, text processing, bit manipulation and a
 * small expression evaluator (shunting-yard) written with plain arrays.
 * Every construct here is translated to TAC and executed. */
#include <stdio.h>
#include <string.h>

#define SAMPLES 40
#define MAXLEN 64
#define STACK 32

unsigned int seed = 12345u;

/* linear congruential generator: unsigned arithmetic wraps by definition */
unsigned int next_random(void) {
    seed = seed * 1103515245u + 12345u;
    return (seed / 65536u) % 32768u;
}

int clamp(int x, int lo, int hi) {
    if (x < lo) return lo;
    if (x > hi) return hi;
    return x;
}

/* ---------- statistics ---------- */

double mean(int v[], int n) {
    long total = 0;
    for (int i = 0; i < n; i++) total += v[i];
    return (double)total / n;
}

double variance(int v[], int n) {
    double m = mean(v, n);
    double acc = 0.0;
    for (int i = 0; i < n; i++) {
        double d = v[i] - m;
        acc += d * d;
    }
    return acc / n;
}

int isqrt(int x) {                      /* integer square root by Newton's method */
    if (x < 2) return x;
    int r = x / 2;
    int prev = 0;
    while (r != prev && r != prev + 1) {
        prev = r;
        r = (r + x / r) / 2;
    }
    while (r * r > x) r--;
    return r;
}

void histogram(int v[], int n, int buckets, int width) {
    int counts[10] = {0};
    for (int i = 0; i < n; i++) {
        int b = v[i] * buckets / 100;
        counts[clamp(b, 0, buckets - 1)]++;
    }
    for (int b = 0; b < buckets; b++) {
        printf("  %2d-%2d | ", b * width, (b + 1) * width - 1);
        for (int k = 0; k < counts[b]; k++) printf("#");
        printf(" %d\n", counts[b]);
    }
}

/* ---------- dynamic programming ---------- */

int lcs(const char *x, const char *y) {
    int n = strlen(x), m = strlen(y);
    int table[MAXLEN][MAXLEN];
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= m; j++) {
            if (i == 0 || j == 0) table[i][j] = 0;
            else if (x[i - 1] == y[j - 1]) table[i][j] = table[i - 1][j - 1] + 1;
            else table[i][j] = table[i - 1][j] > table[i][j - 1] ? table[i - 1][j] : table[i][j - 1];
        }
    }
    return table[n][m];
}

int knapsack(int weight[], int value[], int items, int capacity) {
    int best[64] = {0};
    for (int i = 0; i < items; i++) {
        for (int c = capacity; c >= weight[i]; c--) {
            int with = best[c - weight[i]] + value[i];
            if (with > best[c]) best[c] = with;
        }
    }
    return best[capacity];
}

long count_paths(int rows, int cols) {   /* lattice paths, Pascal-style DP */
    long grid[16][16];
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            grid[r][c] = (r == 0 || c == 0) ? 1 : grid[r - 1][c] + grid[r][c - 1];
    return grid[rows - 1][cols - 1];
}

/* ---------- text ---------- */

void caesar(const char *in, char out[], int shift) {
    int i = 0;
    for (; in[i] != 0; i++) {
        char ch = in[i];
        if (ch >= 'a' && ch <= 'z') ch = (char)('a' + (ch - 'a' + shift) % 26);
        else if (ch >= 'A' && ch <= 'Z') ch = (char)('A' + (ch - 'A' + shift) % 26);
        out[i] = ch;
    }
    out[i] = 0;
}

int is_palindrome(const char *s) {
    int i = 0, j = strlen(s) - 1;
    while (i < j) {
        while (i < j && s[i] == ' ') i++;
        while (i < j && s[j] == ' ') j--;
        if (s[i] != s[j]) return 0;
        i++;
        j--;
    }
    return 1;
}

int count_words(const char *s) {
    int words = 0, inside = 0;
    for (int i = 0; s[i]; i++) {
        if (s[i] == ' ' || s[i] == '\t') inside = 0;
        else if (!inside) { inside = 1; words++; }
    }
    return words;
}

/* ---------- bits ---------- */

int popcount(unsigned int x) {
    int c = 0;
    while (x) { x &= x - 1; c++; }
    return c;
}

unsigned int reverse_bits(unsigned int x) {
    unsigned int r = 0;
    for (int i = 0; i < 32; i++) {
        r = (r << 1) | (x & 1u);
        x >>= 1;
    }
    return r;
}

/* ---------- expression evaluation (shunting-yard with array stacks) ---------- */

int precedence(char op) {
    if (op == '*' || op == '/' || op == '%') return 2;
    if (op == '+' || op == '-') return 1;
    return 0;
}

int apply(int a, int b, char op) {
    switch (op) {
    case '+': return a + b;
    case '-': return a - b;
    case '*': return a * b;
    case '/': return b != 0 ? a / b : 0;
    case '%': return b != 0 ? a % b : 0;
    }
    return 0;
}

int evaluate(const char *expr) {
    int values[STACK], nv = 0;
    char ops[STACK];
    int no = 0;
    for (int i = 0; expr[i]; i++) {
        char ch = expr[i];
        if (ch == ' ') continue;
        if (ch >= '0' && ch <= '9') {
            int v = 0;
            while (expr[i] >= '0' && expr[i] <= '9') { v = v * 10 + (expr[i] - '0'); i++; }
            i--;
            values[nv++] = v;
        } else if (ch == '(') {
            ops[no++] = ch;
        } else if (ch == ')') {
            while (no > 0 && ops[no - 1] != '(') { int b = values[--nv], a = values[--nv]; values[nv++] = apply(a, b, ops[--no]); }
            no--;
        } else {
            while (no > 0 && precedence(ops[no - 1]) >= precedence(ch)) { int b = values[--nv], a = values[--nv]; values[nv++] = apply(a, b, ops[--no]); }
            ops[no++] = ch;
        }
    }
    while (no > 0) { int b = values[--nv], a = values[--nv]; values[nv++] = apply(a, b, ops[--no]); }
    return values[0];
}

int main(void) {
    int sample[SAMPLES];
    for (int i = 0; i < SAMPLES; i++) sample[i] = next_random() % 100;
    int lo = sample[0], hi = sample[0];
    for (int i = 1; i < SAMPLES; i++) {
        if (sample[i] < lo) lo = sample[i];
        if (sample[i] > hi) hi = sample[i];
    }
    printf("== statistics over %d samples ==\n", SAMPLES);
    printf("min=%d max=%d mean=%.3f variance=%.3f isqrt(variance)=%d\n", lo, hi, mean(sample, SAMPLES),
           variance(sample, SAMPLES), isqrt((int)variance(sample, SAMPLES)));
    histogram(sample, SAMPLES, 5, 20);

    printf("== dynamic programming ==\n");
    printf("lcs(\"compiler design\", \"computer science\") = %d\n", lcs("compiler design", "computer science"));
    int weight[5] = {1, 3, 4, 5, 9};
    int value[5] = {1, 4, 5, 7, 11};
    printf("knapsack(capacity 12) = %d\n", knapsack(weight, value, 5, 12));
    printf("lattice paths 8x8 = %ld\n", count_paths(8, 8));

    printf("== text ==\n");
    char secret[MAXLEN];
    caesar("Regular Expressions", secret, 3);
    printf("caesar: %s\n", secret);
    char plain[MAXLEN];
    caesar(secret, plain, 23);
    printf("decoded: %s\n", plain);
    printf("palindrome('never odd or even') = %d, words = %d\n", is_palindrome("never odd or even"), count_words("  never odd  or even "));

    printf("== bits ==\n");
    unsigned int x = 0xF0F0A5u;
    printf("popcount(0x%x) = %d, reversed = 0x%08x\n", x, popcount(x), reverse_bits(x));

    printf("== expressions ==\n");
    printf("2 + 3 * (7 - 4) %% 5 = %d\n", evaluate("2 + 3 * (7 - 4) % 5"));
    printf("(10 + 20) * 3 - 4 / 2 = %d\n", evaluate("(10 + 20) * 3 - 4 / 2"));
    return 0;
}

/* Optimization showcase: each function exercises particular passes.
 * Compare the original and optimized TAC and read the explanations. */
#include <stdio.h>

int folding(void) {
    int seconds = 60 * 60 * 24;          /* constant folding */
    int weeks = seconds * 7;
    return weeks / 3600;
}

int propagation(int n) {
    int scale = 4;                       /* constant propagation through the loop */
    int offset = scale * 2 + 1;
    int total = 0;
    for (int i = 0; i < n; i++) total += i * scale + offset;
    return total;
}

int common_subexpressions(int a, int b) {
    int x = (a + b) * (a + b);           /* a + b computed once (local value numbering) */
    int y = (a + b) * 3;
    int z = a * b + a * b;
    return x + y + z;
}

int loop_invariant(int v[], int n, int k) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        int limit = k * k + 1;           /* does not change inside the loop: hoisted */
        if (v[i] < limit) count++;
    }
    return count;
}

int strength_and_algebra(int x) {
    int a = x * 2;                       /* strength reduction: x + x */
    int b = a + 0;                       /* algebraic simplification */
    int c = b * 1;
    int d = c - c;                       /* always 0 */
    return c + d;
}

int dead_and_unreachable(int x) {
    int debug = 0;
    int unused = x * 37;                 /* never read */
    if (debug) {                         /* debug is always 0: branch removed */
        printf("debug: %d\n", x);
    }
    return x + 1;
}

int unsafe_cases(int x, int y) {
    /* NOT optimized: dividing by a variable could trap, and x / x is not
       always 1 (x may be 0); keeping them preserves the program's behaviour */
    int q = x / y;
    int r = x / x;
    return q + r;
}

int main(void) {
    int data[8] = {3, 9, 1, 12, 5, 7, 2, 10};
    printf("folding=%d\n", folding());
    printf("propagation=%d\n", propagation(10));
    printf("cse=%d\n", common_subexpressions(3, 4));
    printf("licm=%d\n", loop_invariant(data, 8, 2));
    printf("strength=%d\n", strength_and_algebra(21));
    printf("dead=%d\n", dead_and_unreachable(41));
    printf("unsafe=%d\n", unsafe_cases(84, 2));
    return 0;
}

