/* Partial support demo: structs, pointers and malloc are lexed and parsed,
 * but the TAC translator keeps them as opaque operations (shown and counted,
 * never silently dropped), and the optimizer treats them conservatively. */
#include <stdio.h>
#include <stdlib.h>

struct Point {
    int x;
    int y;
};

int manhattan(struct Point *p) {
    return p->x + p->y;
}

int main(void) {
    struct Point p;
    p.x = 3;
    p.y = 4;
    int *buffer = malloc(10 * sizeof(int));
    int n = 2 + 3;                         /* still folded */
    int value = manhattan(&p) + n;
    printf("%d\n", value);
    free(buffer);
    return 0;
}

// Basic: typed declarations, precedence, integer vs floating-point division,
// string concatenation and Java's fixed-width integer wrap-around.
public class Basics {
    static final int WIDTH = 12;
    static final int HEIGHT = 5;

    public static void main(String[] args) {
        int a = 7, b = 3;
        int result = a + b * 2;
        int grouped = (a + b) * 2;
        int area = WIDTH * HEIGHT;
        int unused = area * 100;
        double ratio = (double) area / (2 * (WIDTH + HEIGHT));
        int max = Integer.MAX_VALUE;
        int wrapped = max + 1;                 // defined in Java: wraps to MIN_VALUE
        long wide = (long) max + 1;
        char grade = 'A';
        grade += 2;
        boolean ok = result > grouped || area == 60;
        System.out.println("result=" + result + " grouped=" + grouped);
        System.out.println("area=" + area + " ratio=" + ratio);
        System.out.println("-17 / 5 = " + (-17 / 5) + ", -17 % 5 = " + (-17 % 5));
        System.out.println("wrapped=" + wrapped + " wide=" + wide);
        System.out.println("grade=" + grade + " ok=" + ok + " 1/3=" + (1.0 / 3));
    }
}

// Intermediate: static methods, nested loops, switch, do-while, for-each,
// break/continue and static fields.
public class ControlFlow {
    static int checks = 0;

    static boolean isPrime(int n) {
        checks++;
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        for (int d = 3; d * d <= n; d += 2) {
            if (n % d == 0) return false;
        }
        return true;
    }

    static int collatzLength(long n) {
        int steps = 0;
        while (n != 1) {
            n = (n % 2 == 0) ? n / 2 : 3 * n + 1;
            steps++;
        }
        return steps;
    }

    static String classify(int score) {
        if (score >= 85) return "distinction";
        else if (score >= 70) return "merit";
        else if (score >= 50) return "pass";
        return "fail";
    }

    static int digitSum(int n) {
        int s = 0;
        do {
            s += n % 10;
            n /= 10;
        } while (n > 0);
        return s;
    }

    public static void main(String[] args) {
        int primes = 0, longest = 0, longestAt = 0;
        String line = "";
        for (int i = 1; i <= 30; i++) {
            if (isPrime(i)) {
                line = line + i + " ";
                primes++;
            }
            int len = collatzLength(i);
            if (len > longest) { longest = len; longestAt = i; }
        }
        System.out.println(line);
        System.out.println(primes + " primes below 30 (" + checks + " checks)");
        System.out.println("longest Collatz chain: " + longest + " steps from " + longestAt);

        int[] scores = {92, 47, 70, 68, 85, 50};
        int passed = 0;
        for (int s : scores) {
            String g = classify(s);
            if (g.equals("fail")) continue;
            passed++;
            System.out.println("score " + s + " -> " + g);
        }
        System.out.println(passed + " of " + scores.length + " passed");

        String text = "the quick brown fox jumps over the lazy dog";
        int vowels = 0, es = 0, words = 1;
        for (int i = 0; i < text.length(); i++) {
            switch (text.charAt(i)) {
                case 'e': es++;
                case 'a': case 'i': case 'o': case 'u':
                    vowels++;
                    break;
                case ' ':
                    words++;
                    break;
                default:
                    break;
            }
        }
        System.out.println("vowels=" + vowels + " e=" + es + " words=" + words + " digitSum=" + digitSum(98765));
    }
}

// Intermediate: arrays, recursion, merge sort, binary search and matrices.
import java.util.Arrays;

public class Algorithms {
    static int fib(int n) {
        if (n < 2) return n;
        return fib(n - 1) + fib(n - 2);
    }

    static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    static long power(long base, int exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result *= base;
            base *= base;
            exp >>= 1;
        }
        return result;
    }

    static void mergeSort(int[] a, int[] tmp, int lo, int hi) {
        if (hi - lo < 2) return;
        int mid = (lo + hi) >>> 1;
        mergeSort(a, tmp, lo, mid);
        mergeSort(a, tmp, mid, hi);
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
        while (i < mid) tmp[k++] = a[i++];
        while (j < hi) tmp[k++] = a[j++];
        for (k = lo; k < hi; k++) a[k] = tmp[k];
    }

    static int binarySearch(int[] a, int key) {
        int lo = 0, hi = a.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == key) return mid;
            if (a[mid] < key) lo = mid + 1;
            else hi = mid - 1;
        }
        return -1;
    }

    static int[][] multiply(int[][] a, int[][] b) {
        int n = a.length;
        int[][] c = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                int sum = 0;
                for (int k = 0; k < n; k++) sum += a[i][k] * b[k][j];
